115→// ReadNotes implements the read_notes tool
116→func (h *Handler) ReadNotes(ctx context.Context, req *mcp.CallToolRequest, input note.ReadNotesInput) (*mcp.CallToolResult, note.ReadNotesOutput, error) {
117→	notes := make([]note.NoteContent, 0, len(input.Paths))
118→
119→	for _, path := range input.Paths {
120→		n := note.NoteContent{
121→			Path: path,
122→		}
123→
124→		// Check if path is allowed
125→		allowed, err := h.Vault.IsPathAllowed(path)
126→		if err != nil {
127→			n.Error = fmt.Sprintf("Path validation error: %v", err)
128→			notes = append(notes, n)
129→			continue
130→		}
131→
132→		if !allowed {
133→			n.Error = "Access denied: path is outside vault or is a hidden file"
134→			notes = append(notes, n)
135→			continue
136→		}
137→
138→		// Read file content
139→		content, err := os.ReadFile(path)
140→		if err != nil {
141→			n.Error = fmt.Sprintf("Failed to read file: %v", err)
142→			notes = append(notes, n)
143→			continue
144→		}
145→
146→		n.Content = string(content)
147→		notes = append(notes, n)
148→	}
149→
150→	output := note.ReadNotesOutput{
151→		Notes: notes,
152→	}
153→
154→	// Create text content for the result
155→	var textParts []string
156→	for _, n := range notes {
157→		if n.Error != "" {
158→			textParts = append(textParts, fmt.Sprintf("## %s\nError: %s", n.Path, n.Error))
159→		} else {
160→			textParts = append(textParts, fmt.Sprintf("## %s\n%s", n.Path, n.Content))
161→		}
162→	}
163→
164→	result := &mcp.CallToolResult{
165→		Content: []mcp.Content{
166→			&mcp.TextContent{
167→				Text: strings.Join(textParts, "\n\n"),
168→			},
169→		},
170→	}
171→
172→	return result, output, nil
173→}
