175→// CreateNote implements the create_note tool
176→func (h *Handler) CreateNote(ctx context.Context, req *mcp.CallToolRequest, input note.CreateNoteInput) (*mcp.CallToolResult, note.CreateNoteOutput, error) {
177→	if input.Title == "" {
178→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title is required")
179→	}
180→
181→	slug := note.Slugify(input.Title)
182→	if slug == "" {
183→		return nil, note.CreateNoteOutput{}, fmt.Errorf("title produces an empty slug")
184→	}
185→
186→	today := time.Now().Format("2006-01-02")
187→	filename := today + "_" + slug + ".md"
188→
189→	dir := h.Vault.Path
190→	if input.Folder != "" {
191→		dir = filepath.Join(h.Vault.Path, input.Folder)
192→	}
193→
194→	fullPath := filepath.Join(dir, filename)
195→
196→	allowed, err := h.Vault.IsPathAllowed(fullPath)
197→	if err != nil {
198→		return nil, note.CreateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
199→	}
200→	if !allowed {
201→		return nil, note.CreateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
202→	}
203→
204→	if _, err := os.Stat(fullPath); err == nil {
205→		return nil, note.CreateNoteOutput{}, fmt.Errorf("file already exists: %s", fullPath)
206→	}
207→
208→	if err := os.MkdirAll(dir, 0755); err != nil {
209→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to create directory: %w", err)
210→	}
211→
212→	frontmatter := note.GenerateFrontmatter(input.Tags, today, today)
213→
214→	var content strings.Builder
215→	content.WriteString(frontmatter)
216→	content.WriteString("\n# ")
217→	content.WriteString(input.Title)
218→	content.WriteByte('\n')
219→	if input.Content != "" {
220→		content.WriteByte('\n')
221→		content.WriteString(input.Content)
222→		content.WriteByte('\n')
223→	}
224→
225→	if err := os.WriteFile(fullPath, []byte(content.String()), 0644); err != nil {
226→		return nil, note.CreateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
227→	}
228→
229→	output := note.CreateNoteOutput{Path: fullPath}
230→	result := &mcp.CallToolResult{
231→		Content: []mcp.Content{
232→			&mcp.TextContent{Text: fmt.Sprintf("Created note: %s", fullPath)},
233→		},
234→	}
235→	return result, output, nil
236→}
