284→// DeleteNote implements the delete_note tool
285→func (h *Handler) DeleteNote(ctx context.Context, req *mcp.CallToolRequest, input note.DeleteNoteInput) (*mcp.CallToolResult, note.DeleteNoteOutput, error) {
286→	if !strings.HasSuffix(strings.ToLower(input.Path), ".md") {
287→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("can only delete .md files")
288→	}
289→
290→	allowed, err := h.Vault.IsPathAllowed(input.Path)
291→	if err != nil {
292→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("path validation error: %w", err)
293→	}
294→	if !allowed {
295→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
296→	}
297→
298→	info, err := os.Stat(input.Path)
299→	if os.IsNotExist(err) {
300→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
301→	}
302→	if err != nil {
303→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to stat file: %w", err)
304→	}
305→	if info.IsDir() {
306→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("cannot delete directories")
307→	}
308→
309→	if err := os.Remove(input.Path); err != nil {
310→		return nil, note.DeleteNoteOutput{}, fmt.Errorf("failed to delete file: %w", err)
311→	}
312→
313→	output := note.DeleteNoteOutput(input)
314→	result := &mcp.CallToolResult{
315→		Content: []mcp.Content{
316→			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
317→		},
318→	}
319→	return result, output, nil
320→}
