333→	var results []note.ContentMatch
334→
335→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
336→		if err != nil {
337→			return nil
338→		}
339→
340→		if info.IsDir() {
341→			allowed, checkErr := h.Vault.IsPathAllowed(path)
342→			if checkErr != nil || !allowed {
343→				return filepath.SkipDir
344→			}
345→			return nil
346→		}
347→
348→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
349→			return nil
350→		}
351→
352→		allowed, checkErr := h.Vault.IsPathAllowed(path)
353→		if checkErr != nil || !allowed {
354→			return nil
355→		}
356→
357→		data, err := os.ReadFile(path)
358→		if err != nil {
359→			return nil
360→		}
361→
362→		lines := strings.Split(string(data), "\n")
363→		for lineNum, line := range lines {
364→
365→			matched := false
366→			if useRegex {
367→				matched = re.MatchString(line)
368→			} else {
369→				matched = strings.Contains(strings.ToLower(line), strings.ToLower(query))
370→			}
371→
372→			if matched {
373→				results = append(results, note.ContentMatch{
374→					Path:    path,
375→					Snippet: line,
376→					Line:    lineNum + 1,
377→				})
378→				if len(results) >= vault.MaxSearchResults {
379→					return filepath.SkipAll
380→				}
381→			}
382→		}
383→
384→		return nil
385→	})
386→
387→	if err != nil {
388→		return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
389→	}
390→
391→	output := note.SearchContentOutput{Results: results}
392→
393→	textContent := fmt.Sprintf("Found %d matching lines", len(results))
394→	if len(results) > 0 {
395→		var lines []string
396→		for _, m := range results {
397→			lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
398→		}
399→		textContent += ":\n" + strings.Join(lines, "\n")
400→	}
401→
402→	result := &mcp.CallToolResult{
403→		Content: []mcp.Content{
404→			&mcp.TextContent{Text: textContent},
405→		},
406→	}
407→	return result, output, nil
408→}
409→
410→// GetBacklinks implements the get_backlinks tool
411→func (h *Handler) GetBacklinks(ctx context.Context, req *mcp.CallToolRequest, input note.GetBacklinksInput) (*mcp.CallToolResult, note.GetBacklinksOutput, error) {
412→	if input.NoteName == "" {
413→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("note_name is required")
414→	}
415→
416→	noteName := strings.TrimSuffix(input.NoteName, ".md")
417→	wikilinkRe := regexp.MustCompile(`\[\[([^\]|]+)(?:\|[^\]]+)?\]\]`)
418→
419→	var results []note.Backlink
420→
421→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
422→		if err != nil {
423→			return nil
424→		}
425→
426→		if info.IsDir() {
427→			allowed, checkErr := h.Vault.IsPathAllowed(path)
428→			if checkErr != nil || !allowed {
429→				return filepath.SkipDir
430→			}
431→			return nil
432→		}
433→
434→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
435→			return nil
436→		}
437→
438→		allowed, checkErr := h.Vault.IsPathAllowed(path)
439→		if checkErr != nil || !allowed {
440→			return nil
441→		}
442→
443→		// Exclude the target note itself
444→		baseName := strings.TrimSuffix(filepath.Base(path), ".md")
445→		if strings.EqualFold(baseName, noteName) {
446→			return nil
447→		}
448→
449→		data, err := os.ReadFile(path)
450→		if err != nil {
451→			return nil
452→		}
453→
454→		lines := strings.Split(string(data), "\n")
455→		for _, line := range lines {
456→			matches := wikilinkRe.FindAllStringSubmatch(line, -1)
457→			for _, match := range matches {
458→				if len(match) >= 2 {
459→					linkTarget := strings.TrimSuffix(match[1], ".md")
460→					if strings.EqualFold(linkTarget, noteName) {
461→						results = append(results, note.Backlink{
462→							Path: path,
463→							Line: line,
464→						})
465→						break // one match per line is enough
466→					}
467→				}
468→			}
469→		}
470→
471→		return nil
472→	})
473→
474→	if err != nil {
475→		return nil, note.GetBacklinksOutput{}, fmt.Errorf("failed to search backlinks: %w", err)
476→	}
477→
478→	output := note.GetBacklinksOutput{Results: results}
479→
480→	textContent := fmt.Sprintf("Found %d backlinks to [[%s]]", len(results), noteName)
481→	if len(results) > 0 {
482→		var lines []string
483→		for _, bl := range results {
484→			lines = append(lines, fmt.Sprintf("%s: %s", bl.Path, bl.Line))
485→		}
486→		textContent += ":\n" + strings.Join(lines, "\n")
487→	}
488→
489→	result := &mcp.CallToolResult{
490→		Content: []mcp.Content{
491→			&mcp.TextContent{Text: textContent},
492→		},
493→	}
494→	return result, output, nil
495→}
496→
497→// ListTags implements the list_tags tool
498→func (h *Handler) ListTags(ctx context.Context, req *mcp.CallToolRequest, input note.ListTagsInput) (*mcp.CallToolResult, note.ListTagsOutput, error) {
499→	tagCounts := make(map[string]int)
500→
501→	// Regex for inline #tags (not inside code blocks)
502→	inlineTagRe := regexp.MustCompile(`(?:^|\s)#([a-zA-Z][a-zA-Z0-9_/-]*)`)
503→
504→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
505→		if err != nil {
506→			return nil
507→		}
508→
509→		if info.IsDir() {
510→			allowed, checkErr := h.Vault.IsPathAllowed(path)
511→			if checkErr != nil || !allowed {
512→				return filepath.SkipDir
513→			}
514→			return nil
515→		}
516→
517→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
518→			return nil
519→		}
520→
521→		allowed, checkErr := h.Vault.IsPathAllowed(path)
522→		if checkErr != nil || !allowed {
523→			return nil
524→		}
525→
526→		data, err := os.ReadFile(path)
527→		if err != nil {
528→			return nil
529→		}
530→
531→		content := string(data)
532→
533→		// Parse frontmatter tags
534→		if strings.HasPrefix(content, "---\n") {
535→			endIdx := strings.Index(content[4:], "\n---\n")
536→			if endIdx >= 0 {
537→				frontmatter := content[4 : 4+endIdx]
538→				note.ParseFrontmatterTags(frontmatter, tagCounts)
539→			}
540→		}
541→
542→		// Parse inline #tags (skip code blocks)
543→		lines := strings.Split(content, "\n")
544→		inCodeBlock := false
545→		for _, line := range lines {
546→			if strings.HasPrefix(strings.TrimSpace(line), "```") {
547→				inCodeBlock = !inCodeBlock
548→				continue
549→			}
550→			if inCodeBlock {
551→				continue
552→			}
553→			matches := inlineTagRe.FindAllStringSubmatch(line, -1)
554→			for _, match := range matches {
555→				if len(match) >= 2 {
556→					tagCounts[match[1]]++
557→				}
558→			}
559→		}
560→
561→		return nil
562→	})
563→
564→	if err != nil {
565→		return nil, note.ListTagsOutput{}, fmt.Errorf("failed to list tags: %w", err)
566→	}
567→
568→	// Filter by prefix and sort
569→	var tags []note.TagCount
570→	for tag, count := range tagCounts {
571→		if input.Prefix == "" || strings.HasPrefix(tag, input.Prefix) {
572→			tags = append(tags, note.TagCount{Tag: tag, Count: count})
573→		}
574→	}
575→	sort.Slice(tags, func(i, j int) bool {
576→		return tags[i].Tag < tags[j].Tag
577→	})
578→
579→	output := note.ListTagsOutput{Tags: tags}
580→
581→	textContent := fmt.Sprintf("Found %d unique tags", len(tags))
582→	if len(tags) > 0 {
583→		var lines []string
584→		for _, tc := range tags {
585→			lines = append(lines, fmt.Sprintf("#%s (%d)", tc.Tag, tc.Count))
586→		}
587→		textContent += ":\n" + strings.Join(lines, "\n")
588→	}
589→
590→	result := &mcp.CallToolResult{
591→		Content: []mcp.Content{
592→			&mcp.TextContent{Text: textContent},
593→		},
594→	}
595→	return result, output, nil
596→}
