 15→	"github.com/nsega/mcp-obsidian/internal/vault"
 16→)
 17→
 18→// Handler holds the vault reference and provides MCP tool handler methods
 19→type Handler struct {
 20→	Vault *vault.Vault
 21→}
 22→
 23→// New creates a new Handler with the given Vault
 24→func New(v *vault.Vault) *Handler {
 25→	return &Handler{Vault: v}
 26→}
 27→
 28→// SearchNotes implements the search_notes tool
 29→func (h *Handler) SearchNotes(ctx context.Context, req *mcp.CallToolRequest, input note.SearchNotesInput) (*mcp.CallToolResult, note.SearchNotesOutput, error) {
 30→	var results []string
 31→	query := input.Query
 32→
 33→	// Try to compile as regex, if it fails, use literal string matching
 34→	var re *regexp.Regexp
 35→	var useRegex bool
 36→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
 37→		re = compiled
 38→		useRegex = true
 39→	}
 40→
 41→	// Walk through the vault directory
 42→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
 43→		if err != nil {
 44→			return nil // Skip files with errors
 45→		}
 46→
 47→		// Skip directories
 48→		if info.IsDir() {
 49→			// Check if directory is allowed (not hidden)
 50→			allowed, checkErr := h.Vault.IsPathAllowed(path)
 51→			if checkErr != nil || !allowed {
 52→				return filepath.SkipDir
 53→			}
 54→			return nil
 55→		}
 56→
 57→		// Only process markdown files
 58→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
 59→			return nil
 60→		}
 61→
 62→		// Check if file is allowed
 63→		allowed, checkErr := h.Vault.IsPathAllowed(path)
 64→		if checkErr != nil || !allowed {
 65→			return nil
 66→		}
 67→
 68→		// Get filename
 69→		filename := filepath.Base(path)
 70→
 71→		// Match against query
 72→		matched := false
 73→		if useRegex {
 74→			matched = re.MatchString(filename)
 75→		} else {
 76→			matched = strings.Contains(strings.ToLower(filename), strings.ToLower(query))
 77→		}
 78→
 79→		if matched {
 80→			results = append(results, path)
 81→			// Limit results
 82→			if len(results) >= vault.MaxSearchResults {
 83→				return filepath.SkipAll
 84→			}
 85→		}
 86→
 87→		return nil
 88→	})
 89→
 90→	if err != nil {
 91→		return nil, note.SearchNotesOutput{}, fmt.Errorf("failed to search notes: %w", err)
 92→	}
 93→
 94→	output := note.SearchNotesOutput{
 95→		Results: results,
 96→	}
 97→
 98→	// Create text content for the result
