238→// UpdateNote implements the update_note tool
239→func (h *Handler) UpdateNote(ctx context.Context, req *mcp.CallToolRequest, input note.UpdateNoteInput) (*mcp.CallToolResult, note.UpdateNoteOutput, error) {
240→	allowed, err := h.Vault.IsPathAllowed(input.Path)
241→	if err != nil {
242→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("path validation error: %w", err)
243→	}
244→	if !allowed {
245→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("access denied: path is outside vault or is a hidden file")
246→	}
247→
248→	if _, err := os.Stat(input.Path); os.IsNotExist(err) {
249→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("file does not exist: %s", input.Path)
250→	}
251→
252→	mode := input.Mode
253→	if mode == "" {
254→		mode = "replace"
255→	}
256→
257→	switch mode {
258→	case "replace":
259→		if err := os.WriteFile(input.Path, []byte(input.Content), 0644); err != nil {
260→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
261→		}
262→	case "append":
263→		existing, err := os.ReadFile(input.Path)
264→		if err != nil {
265→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to read file: %w", err)
266→		}
267→		newContent := string(existing) + "\n\n" + input.Content
268→		if err := os.WriteFile(input.Path, []byte(newContent), 0644); err != nil {
269→			return nil, note.UpdateNoteOutput{}, fmt.Errorf("failed to write file: %w", err)
270→		}
271→	default:
272→		return nil, note.UpdateNoteOutput{}, fmt.Errorf("invalid mode: %s (must be 'replace' or 'append')", mode)
273→	}
274→
275→	output := note.UpdateNoteOutput{Path: input.Path}
276→	result := &mcp.CallToolResult{
277→		Content: []mcp.Content{
278→			&mcp.TextContent{Text: fmt.Sprintf("Updated note (%s): %s", mode, input.Path)},
279→		},
280→	}
281→	return result, output, nil
282→}
