322→// SearchContent implements the search_content tool
323→func (h *Handler) SearchContent(ctx context.Context, req *mcp.CallToolRequest, input note.SearchContentInput) (*mcp.CallToolResult, note.SearchContentOutput, error) {
324→	query := input.Query
325→
326→	var re *regexp.Regexp
327→	var useRegex bool
328→	if compiled, err := regexp.Compile("(?i)" + query); err == nil {
329→		re = compiled
330→		useRegex = true
331→	}
332→
333→	var results []note.ContentMatch
334→
335→	err := filepath.Walk(h.Vault.Path, func(path string, info os.FileInfo, err error) error {
336→		if err != nil {
337→			return nil
338→		}
339→
340→		if info.IsDir() {
341→			allowed, checkErr := h.Vault.IsPathAllowed(path)
342→			if checkErr != nil || !allowed {
343→				return filepath.SkipDir
344→			}
345→			return nil
346→		}
347→
348→		if !strings.HasSuffix(strings.ToLower(path), ".md") {
349→			return nil
350→		}
351→
352→		allowed, checkErr := h.Vault.IsPathAllowed(path)
353→		if checkErr != nil || !allowed {
354→			return nil
355→		}
356→
357→		data, err := os.ReadFile(path)
358→		if err != nil {
359→			return nil
360→		}
361→
362→		lines := strings.Split(string(data), "\n")
363→		for lineNum, line := range lines {
364→
365→			matched := false
366→			if useRegex {
367→				matched = re.MatchString(line)
368→			} else {
369→				matched = strings.Contains(strings.ToLower(line), strings.ToLower(query))
370→			}
371→
372→			if matched {
373→				results = append(results, note.ContentMatch{
374→					Path:    path,
375→					Snippet: line,
376→					Line:    lineNum + 1,
377→				})
378→				if len(results) >= vault.MaxSearchResults {
379→					return filepath.SkipAll
380→				}
381→			}
382→		}
383→
384→		return nil
385→	})
386→
387→	if err != nil {
388→		return nil, note.SearchContentOutput{}, fmt.Errorf("failed to search content: %w", err)
389→	}
390→
391→	output := note.SearchContentOutput{Results: results}
392→
393→	textContent := fmt.Sprintf("Found %d matching lines", len(results))
394→	if len(results) > 0 {
395→		var lines []string
396→		for _, m := range results {
397→			lines = append(lines, fmt.Sprintf("%s:%d: %s", m.Path, m.Line, m.Snippet))
398→		}
399→		textContent += ":\n" + strings.Join(lines, "\n")
400→	}
