			continue
		}

		if !allowed {
			n.Error = "Access denied: path is outside vault or is a hidden file"
			notes = append(notes, n)
			continue
		}

		// Read file content
		content, err := os.ReadFile(path)
		if err != nil {
			n.Error = fmt.Sprintf("Failed to read file: %v", err)
