	output := note.DeleteNoteOutput(input)
	result := &mcp.CallToolResult{
		Content: []mcp.Content{
			&mcp.TextContent{Text: fmt.Sprintf("Deleted note: %s", input.Path)},
		},
	}
	return result, output, nil
}

